CREATE DEFINER=`u307626220_EWC_DB`@`127.0.0.1` PROCEDURE `update_customer_opening_balance` ()   BEGIN
    DECLARE v_old_year VARCHAR(8)
CHARACTER SET utf8mb4
COLLATE utf8mb4_general_ci;

DECLARE v_new_year VARCHAR(8)
CHARACTER SET utf8mb4
COLLATE utf8mb4_general_ci;
    DECLARE v_year INT;

    SET v_year = YEAR(CURDATE());

    -- This procedure should normally run on or after 1 April.
    SET v_old_year = CONCAT(v_year - 1, '-', RIGHT(v_year, 2));
    SET v_new_year = CONCAT(v_year, '-', RIGHT(v_year + 1, 2));

        customer_id,
        financial_year,
        opening_balance,
        created_by
    )
    SELECT
        c.customer_id,
        v_new_year,
        COALESCE(ob.opening_balance,0)
        + COALESCE(SUM(cl.debit - cl.credit),0),
        'System'
    FROM customer c
    LEFT JOIN customer_opening_balance ob
           ON ob.customer_id = c.customer_id
          AND ob.financial_year = v_old_year
    LEFT JOIN customer_ledger cl
           ON cl.customer_id = c.customer_id
          AND cl.financial_year = v_old_year
    GROUP BY
        c.customer_id,
        ob.opening_balance
    ON DUPLICATE KEY UPDATE
        opening_balance = VALUES(opening_balance),
        modified_on = NOW(),
        modified_by = 'System';

END$$

CREATE DEFINER=`u307626220_EWC_DB`@`127.0.0.1` PROCEDURE `update_sales_customer_ledger` (IN `p_date` DATE)   BEGIN
DECLARE v_financial_year VARCHAR(8);

    -- Calculate Financial Year
    IF MONTH(p_date) >= 4 THEN
        SET v_financial_year =
            CONCAT(YEAR(p_date), '-', RIGHT(YEAR(p_date) + 1, 2));
    ELSE
        SET v_financial_year =
            CONCAT(YEAR(p_date) - 1, '-', RIGHT(YEAR(p_date), 2));
    END IF;


    -- Delete existing ledger entries for the date
    DELETE
    FROM customer_ledger
    WHERE source_type = 'Sales'
      AND DATE(trans_date) = p_date;

    -- Sales Invoices
        customer_id,
        financial_year,
        trans_date,
        source_type,
        trans_id,
        payment_id,
        debit,
        credit,
        remarks,
        created_by
        )
    SELECT
        customer,
        v_financial_year,
        trans_date,
        'Sales',
        trans_id,
        NULL,
        trans_amount,
        0,
        'Sales Invoice',
        'Admin'
    FROM sales_trans
    WHERE DATE(trans_date) = p_date;

    -- Customer Receipts
        customer_id,
        financial_year,
        trans_date,
        source_type,
        trans_id,
        payment_id,
        debit,
        credit,
        remarks,
        created_by
     
    )
    SELECT
        s.customer,
        v_financial_year,
        p.payment_date,
        'Sales',
        pt.trans_id,
        pt.payment_id,
        0,
        pt.amount_settled,
        'Receipt',
        'Admin'
     
    FROM payments p
    INNER JOIN pay_track pt
            ON p.payment_id = pt.payment_id
    INNER JOIN sales_trans s
            ON s.trans_id = pt.trans_id
    WHERE DATE(p.payment_date) = p_date;

END$$

CREATE DEFINER=`u307626220_EWC_DB`@`127.0.0.1` PROCEDURE `update_service_customer_ledger` (IN `p_date` DATE)   BEGIN
DECLARE v_financial_year VARCHAR(8);

    -- Calculate Financial Year
    IF MONTH(p_date) >= 4 THEN
        SET v_financial_year =
            CONCAT(YEAR(p_date), '-', RIGHT(YEAR(p_date) + 1, 2));
    ELSE
        SET v_financial_year =
            CONCAT(YEAR(p_date) - 1, '-', RIGHT(YEAR(p_date), 2));
    END IF;


    /* Delete existing Service Ledger entries for the date */

    DELETE
    FROM customer_ledger
    WHERE source_type = 'Service'
      AND DATE(trans_date) = p_date;

    /* GST Service Invoices */

        customer_id,
        financial_year,
        trans_date,
        source_type,
        trans_id,
        payment_id,
        debit,
        credit,
        remarks,
        created_by
    )
    SELECT
        customer,
        v_financial_year,
        trans_date,
        'Service',
        trans_id,
        NULL,
        trans_amount,
        0,
        'Service Invoice',
        'Admin'
    FROM service_trans
    WHERE DATE(trans_date) = p_date
      AND gst = 'Y';

    /* Customer Receipts */

        customer_id,
        financial_year,
        trans_date,
        source_type,
        trans_id,
        payment_id,
        debit,
        credit,
        remarks,
        created_by
    )
    SELECT
        s.customer,
        v_financial_year,
        p.payment_date,
        'Service',
        pt.trans_id,
        pt.payment_id,
        0,
        pt.amount_settled,
        'Receipt',
        'Admin'
    FROM payments p
    INNER JOIN pay_track pt
            ON p.payment_id = pt.payment_id
    INNER JOIN service_trans s
            ON s.trans_id = pt.trans_id
    WHERE DATE(p.payment_date) = p_date
      AND s.gst = 'Y';

END$$

